/**
 * Release Notes Formatter & Sanitizer
 *
 * Formats release notes from GitHub / electron-updater:
 * - Supports pre-compiled HTML strings (generated by electron-builder from GitHub releases)
 * - Supports raw Markdown strings (from direct GitHub API fallback or custom feeds)
 * - Safely sanitizes HTML (stripping malicious tags, scripts, inline event handlers)
 * - Restricts link URLs to safe protocols and opens them externally
 */

export const ALLOWED_TAGS = new Set([
  'h1', 'h2', 'h3', 'h4', 'h5', 'h6',
  'p', 'ul', 'ol', 'li',
  'strong', 'b', 'em', 'i', 'u', 's', 'del',
  'code', 'pre', 'a', 'br', 'hr', 'blockquote',
  'span', 'div', 'table', 'thead', 'tbody', 'tr', 'th', 'td'
]);

export const DANGEROUS_TAGS = new Set([
  'script', 'style', 'iframe', 'frame', 'object', 'embed',
  'form', 'input', 'button', 'select', 'textarea', 'meta', 'link', 'svg'
]);

/**
 * Converts Markdown syntax to HTML if the input is not already structured HTML.
 */
export function convertMarkdownToHtml(raw: string): string {
  if (!raw || typeof raw !== 'string') return '';
  let text = raw.replace(/\r\n/g, '\n');

  // If already structured HTML (contains block-level HTML tags), return directly
  if (/<(?:h[1-6]|ul|ol|li|p|div|table|blockquote)\b/i.test(text)) {
    return text;
  }

  // Preserve fenced code blocks from line and inline parsing
  const codeBlocks: string[] = [];
  text = text.replace(/```([a-zA-Z0-9_-]*)\n([\s\S]*?)```/g, (_match, _lang, code) => {
    const idx = codeBlocks.length;
    const escaped = code
      .replace(/&/g, '&amp;')
      .replace(/</g, '&lt;')
      .replace(/>/g, '&gt;');
    codeBlocks.push(`<pre><code>${escaped}</code></pre>`);
    return `%%CODEBLOCK_${idx}%%`;
  });

  const lines = text.split('\n');
  const output: string[] = [];
  let inUl = false;
  let inOl = false;

  for (let i = 0; i < lines.length; i++) {
    const line = lines[i];
    const trimmed = line.trim();

    // Horizontal rule: ---, ***, ___
    if (/^(?:---+|\*\*\*+|___+)\s*$/.test(trimmed)) {
      if (inUl) { output.push('</ul>'); inUl = false; }
      if (inOl) { output.push('</ol>'); inOl = false; }
      output.push('<hr/>');
      continue;
    }

    // Headings # through ######
    const headingMatch = line.match(/^(#{1,6})\s+(.*)$/);
    if (headingMatch) {
      if (inUl) { output.push('</ul>'); inUl = false; }
      if (inOl) { output.push('</ol>'); inOl = false; }
      const level = headingMatch[1].length;
      output.push(`<h${level}>${headingMatch[2]}</h${level}>`);
      continue;
    }

    // Blockquotes >
    const quoteMatch = line.match(/^>\s?(.*)$/);
    if (quoteMatch) {
      if (inUl) { output.push('</ul>'); inUl = false; }
      if (inOl) { output.push('</ol>'); inOl = false; }
      output.push(`<blockquote>${quoteMatch[1]}</blockquote>`);
      continue;
    }

    // Unordered list items: - or * or +
    const ulMatch = line.match(/^[-*+]\s+(.*)$/);
    if (ulMatch) {
      if (inOl) { output.push('</ol>'); inOl = false; }
      if (!inUl) { output.push('<ul>'); inUl = true; }
      output.push(`<li>${ulMatch[1]}</li>`);
      continue;
    }

    // Ordered list items: 1.
    const olMatch = line.match(/^\d+\.\s+(.*)$/);
    if (olMatch) {
      if (inUl) { output.push('</ul>'); inUl = false; }
      if (!inOl) { output.push('<ol>'); inOl = true; }
      output.push(`<li>${olMatch[1]}</li>`);
      continue;
    }

    // Empty lines break paragraphs
    if (!trimmed) {
      if (inUl) { output.push('</ul>'); inUl = false; }
      if (inOl) { output.push('</ol>'); inOl = false; }
      continue;
    }

    // Regular text paragraph line
    if (inUl) { output.push('</ul>'); inUl = false; }
    if (inOl) { output.push('</ol>'); inOl = false; }
    output.push(`<p>${line}</p>`);
  }

  if (inUl) output.push('</ul>');
  if (inOl) output.push('</ol>');

  let result = output.join('\n');

  // Inline formatting
  // Markdown links: [text](https://...)
  result = result.replace(/\[([^\]]+)\]\((https?:\/\/[^\s)]+)\)/g, '<a href="$2" target="_blank" rel="noopener noreferrer">$1</a>');
  // Bold: **text** or __text__
  result = result.replace(/(?:\*\*|__)(.*?)(?:\*\*|__)/g, '<strong>$1</strong>');
  // Italic: *text* or _text_
  result = result.replace(/(?:^|[^\*])\*([^\*\n]+)\*(?!\*)/g, (match, p1) => {
    return match[0] === '*' ? `<em>${p1}</em>` : `${match[0]}<em>${p1}</em>`;
  });
  // Inline code: `code`
  result = result.replace(/`([^`\n]+)`/g, '<code>$1</code>');
  // Strikethrough: ~~text~~
  result = result.replace(/~~(.*?)~~/g, '<del>$1</del>');

  // Restore code blocks
  result = result.replace(/%%CODEBLOCK_(\d+)%%/g, (_, idx) => codeBlocks[Number(idx)] || '');

  return result;
}

/**
 * Fallback sanitizer for Node/test environments or when DOMParser is unavailable.
 */
export function fallbackSanitize(html: string): string {
  if (!html || typeof html !== 'string') return '';
  let sanitized = html
    .replace(/<script\b[^<]*(?:(?!<\/script>)<[^<]*)*<\/script>/gi, '')
    .replace(/<style\b[^<]*(?:(?!<\/style>)<[^<]*)*<\/style>/gi, '')
    .replace(/<iframe\b[^<]*(?:(?!<\/iframe>)<[^<]*)*<\/iframe>/gi, '')
    .replace(/<\/?(?:script|style|iframe|frame|object|embed|form|input|button|select|textarea|meta|link|svg)\b[^>]*>/gi, '');

  // Strip all inline event handlers (onclick, onerror, onload, etc.)
  sanitized = sanitized.replace(/\s+on[a-zA-Z]+\s*=\s*(?:"[^"]*"|'[^']*'|[^\s>]+)/gi, '');

  // Strip dangerous javascript: or data: URIs
  sanitized = sanitized.replace(/\s+(?:href|src)\s*=\s*["']?\s*(?:javascript|data|vbscript):[^'">\s]*/gi, '');

  // Strip non-whitelisted tags and sanitize allowed tags
  sanitized = sanitized.replace(/<\/?([a-zA-Z0-9]+)\b([^>]*)>/g, (match, tag, rawAttrs) => {
    const lower = tag.toLowerCase();
    if (ALLOWED_TAGS.has(lower)) {
      if (lower === 'a') {
        const hrefMatch = (rawAttrs || '').match(/href\s*=\s*("[^"]*"|'[^']*'|[^\s>]+)/i);
        const href = hrefMatch ? ` ${hrefMatch[0]}` : '';
        return match.startsWith('</') ? '</a>' : `<a${href} target="_blank" rel="noopener noreferrer">`;
      }
      return match;
    }
    return '';
  });

  return sanitized;
}

/**
 * Sanitizes an HTML string using Chromium's DOMParser in the browser,
 * or fallbackSanitize in Node environments.
 */
export function sanitizeReleaseNotesHtml(rawHtml: string): string {
  if (!rawHtml || typeof rawHtml !== 'string') return '';

  if (typeof DOMParser !== 'undefined' && typeof document !== 'undefined') {
    try {
      const parser = new DOMParser();
      const doc = parser.parseFromString(rawHtml, 'text/html');

      const cleanNode = (node: Node): Node | null => {
        if (node.nodeType === Node.TEXT_NODE) {
          return document.createTextNode(node.textContent || '');
        }
        if (node.nodeType === Node.ELEMENT_NODE) {
          const el = node as HTMLElement;
          const tag = el.tagName.toLowerCase();

          if (DANGEROUS_TAGS.has(tag)) {
            return null;
          }

          if (!ALLOWED_TAGS.has(tag)) {
            // Unwrap children for non-whitelisted container tags
            const frag = document.createDocumentFragment();
            Array.from(el.childNodes).forEach((child) => {
              const cleaned = cleanNode(child);
              if (cleaned) frag.appendChild(cleaned);
            });
            return frag;
          }

          const cleanEl = document.createElement(tag);

          if (tag === 'a') {
            const href = (el.getAttribute('href') || '').trim();
            if (/^(?:https?:\/\/|mailto:)/i.test(href)) {
              cleanEl.setAttribute('href', href);
              cleanEl.setAttribute('target', '_blank');
              cleanEl.setAttribute('rel', 'noopener noreferrer');
            }
          }

          Array.from(el.childNodes).forEach((child) => {
            const cleaned = cleanNode(child);
            if (cleaned) cleanEl.appendChild(cleaned);
          });

          return cleanEl;
        }
        return null;
      };

      const wrapper = document.createElement('div');
      Array.from(doc.body.childNodes).forEach((child) => {
        const cleaned = cleanNode(child);
        if (cleaned) wrapper.appendChild(cleaned);
      });

      return wrapper.innerHTML;
    } catch {
      return fallbackSanitize(rawHtml);
    }
  }

  return fallbackSanitize(rawHtml);
}

/**
 * Formats release notes string into sanitized, rich HTML.
 */
export function formatReleaseNotesHtml(raw: string): string {
  if (!raw || typeof raw !== 'string') return '';
  const converted = convertMarkdownToHtml(raw);
  return sanitizeReleaseNotesHtml(converted);
}
